fn generate_carapace_spec() -> String {
    r#"# yaml-language-server: $schema=https://carapace.sh/schemas/command.json
name: forgum
description: Modern animated terminal mascot engine
flags:
  --cow=: Animal mascot name
  --animal=: Animal mascot name
  --effect=: Animation effect
  --mountain=: Mountain / horizon style
  --road=: Road / ground style
  --environment=: Environment particle effect
  --color-mode=: Color rendering mode
  --text=: Text inside speech bubble
  --duration=: Duration in seconds (0 = infinite)
  --fps=: Target frames per second
  --thought-interval=: Interval in seconds for thought rotation
  --eyes=: Custom eyes string
  --tongue=: Custom tongue string
  --palette=: Custom hex palette
  --think: Render in cowthink mode
  --background: Render above prompt as non-blocking overlay
  --banner: Render inline as animated banner
  --split-scroll: Lock terminal scroll margins below animation
completion:
  flag:
    cow: ["default\tStandard bovine mascot", "dragon\tFire-breathing dragon", "tux\tLinux penguin", "cat\tPlayful feline", "ghost\tSpooky phantom", "elephant\tGentle giant", "bunny\tCute rabbit", "corgi\tPlayful corgi", "fox\tWoodland fox", "random\tPick random mascot"]
    animal: ["default\tStandard bovine mascot", "dragon\tFire-breathing dragon", "tux\tLinux penguin", "cat\tPlayful feline", "ghost\tSpooky phantom", "elephant\tGentle giant", "bunny\tCute rabbit", "corgi\tPlayful corgi", "fox\tWoodland fox", "random\tPick random mascot"]
    effect: ["walk\tNatural bovine walking animation", "breathe\tGentle breathing idle animation", "float\tDrifting levitation animation", "fly\tFlying creature animation", "talk\tConversational speech animation", "sway\tSwaying pendulum animation", "pulse\tPulsing scale animation", "glitch\tDigital cyberpunk glitch animation", "particles\tAmbient particle emitter animation", "dissolve\tDissolve and materialize animation"]
    mountain: ["hills\tRolling verdant hills", "peaks\tAlpine peaks", "volcano\tActive volcano", "iceberg\tGlacier ridges", "skyline\tUrban skyline", "seamount\tUnderwater ridges", "plateau\tDesert mesa", "crater\tImpact rim", "gothic\tSpire silhouette", "castle\tFortress ramparts", "garden\tTerraced hedge", "none\tDisable mountains"]
    road: ["dirt\tCountryside dirt trail", "cobblestone\tStone pavement", "magma\tVolcanic basalt", "ice\tPacked crystalline ice", "seabed\tRipple sands", "sidewalk\tPaved asphalt", "roof\tRoof shingles", "grid\tNeon cyber grid", "crypt\tCatacomb flagstones", "savanna\tArid trail", "mud\tSquishy soil", "tracks\tRailroad ties", "checkerboard\tDual tiles", "none\tDisable road"]
    environment: ["pasture\tOpen meadows", "inferno\tBlazing magma", "ocean\tAquatic realm", "arctic\tFrozen tundra", "city\tMetropolitan skyline", "forest\tAncient woodlands", "savanna\tGolden plains", "swamp\tMurky bayou", "space\tCosmos void", "cyber\tDigital matrix", "graveyard\tGothic cemetery", "jurassic\tPrimeval wilds", "hive\tBio hive", "throne\tGothic sanctuary", "none\tDisable particles"]
    color-mode: ["animal\tCreature archetype colors", "rainbow\tDynamic spectrum", "solid\tSingle pure hue", "none\tMonochrome terminal default"]
commands:
  - name: render
    description: Render mascot animation (default)
  - name: think
    description: Render in cowthink mode
  - name: fortune
    description: Print a random fortune
  - name: options
    description: Display available options in structured tables
  - name: completions
    description: Install shell completions and attach to profile
  - name: init
    description: Generate shell integration hook
  - name: tui
    description: Interactive terminal UI
  - name: status
    description: Print engine status
  - name: doctor
    description: Diagnose configuration and capabilities
  - name: checkhealth
    description: Run comprehensive system health check
  - name: config
    description: View or edit configuration
  - name: logs
    description: View, stream, or clear engine logs
  - name: herd
    description: Fleet manager for background daemons
  - name: theme
    description: Manage mascot theme
  - name: demo
    description: Run showcase demo
  - name: showcase
    description: Run 60-second demo reel
  - name: say
    description: Run command and display output in speech bubble
"#.to_string()
}

fn generate_xonsh_completions() -> String {
    r#"# Xonsh completion specification for Forgum
from xonsh.completers.tools import *

@contextual_command_completer_for("forgum")
def _forgum_completer(command):
    opts = {
        "--animal", "--cow", "-a", "--effect", "-e", "--mountain", "--road",
        "--environment", "--color-mode", "--text", "--duration", "-d",
        "--fps", "--thought-interval", "--eyes", "--tongue", "--palette",
        "--think", "--background", "-b", "--banner", "-B", "--split-scroll",
        "render", "think", "fortune", "options", "list", "completions",
        "init", "tui", "status", "doctor", "checkhealth", "config", "logs",
        "herd", "theme", "demo", "showcase", "say", "help"
    }
    return opts
"#
    .to_string()
}

