fn generate_yash_completions() -> String {
    r#"# Yash completion for Forgum
function completion/forgum {
    typeset -a commands
    commands=(render think fortune list completions init tui status doctor checkhealth config logs herd theme demo showcase say help)
    complete -c commands
}
"#.to_string()
}
